/*
 * gbasis.c -- Groebner bases over Q.
 *
 * What it computes
 *   groebner(polys, vars, order) returns the reduced Groebner basis of the
 *   ideal generated by `polys` in Q[vars], as a list of expressions, each
 *   monic (leading coefficient 1) and sorted by ascending leading monomial.
 *   With the lex order and vars = [x1, ..., xn] (x1 > x2 > ... > xn) the
 *   result is "triangular": the first elements involve only the last
 *   variables, which is what solve() exploits (elimination theorem).
 *
 * Callers
 *   - cmds.c, command gbasis(polys, vars [, plex|lex|tdeg|grevlex]).
 *   - solve.c, solve_system(): a lex basis turns a polynomial system into a
 *     triangular one that is then solved by back-substitution.
 *
 * Algorithm (Buchberger's algorithm, see Buchberger 1965/1979; Cox, Little &
 * O'Shea "Ideals, Varieties, and Algorithms" ch. 2; Becker & Weispfenning
 * "Groebner Bases"; Geddes/Czapor/Labahn "Algorithms for Computer Algebra"
 * ch. 10):
 *   1. Convert every input to a sparse distributed polynomial (below), make it
 *      monic, and put all pairs (i, j) into the pair set P.
 *   2. Repeatedly take the pair with the smallest lcm(LM(g_i), LM(g_j)) in
 *      the term order ("normal selection strategy"), skip it if one of
 *      Buchberger's criteria shows the S-polynomial reduces to 0:
 *        - product criterion: LM(g_i) and LM(g_j) are coprime;
 *        - chain criterion (Buchberger's second criterion, classical form):
 *          some g_k has LM(g_k) | lcm(i, j) and both pairs (i, k), (j, k)
 *          have already left P.  This is the pair-by-pair test, not the full
 *          Gebauer-Moeller pair-set update.
 *      otherwise reduce S(g_i, g_j) fully modulo the current basis; a nonzero
 *      remainder is made monic, appended, and paired with all elements.
 *   3. A constant remainder means the ideal is (1): return [1] at once.
 *   4. Minimise (drop elements whose leading monomial is divisible by another
 *      leading monomial) and interreduce (reduce every tail modulo the
 *      others), which gives the unique reduced basis.
 *
 * Representation
 *   A polynomial (GP) is an array of terms sorted in strictly DEcreasing term
 *   order, so term 0 is the leading term.  Term i has a rational coefficient
 *   c[i] (an E_INT or E_RAT node) and an exponent vector of g_nv uint16_t
 *   entries stored at e + i * g_nv (macro EXP).  The zero polynomial has
 *   n = 0.  Variables are numbered as in `vars`; variable 0 is the largest.
 *
 * Memory and limits
 *   Everything lives in scratch and is never released inside this module;
 *   polynomials are rebuilt rather than mutated (gp_axpy returns a fresh GP),
 *   so a GP value may share arrays with older ones.  Hard limits keep the
 *   computation bounded on the calculator: at most GMAXV variables, 256 basis
 *   elements, 4096 simultaneously pending pairs, 5000 pair selections and
 *   200000 reduction steps per reduction; exceeding any of them raises
 *   CAS_ERR_UNSUPPORTED via cas_throw.  Long loops poll for interrupts.
 *
 * Global state
 *   g_nv / g_order (number of variables, term order) are file-level statics
 *   used by every helper; groebner() saves and restores them on normal
 *   return (not when an error longjmps out).  Not reentrant / thread-safe,
 *   like the rest of the engine.
 */
#include "cas_int.h"
#include <string.h>

/* cold code: compiled for size (flash bank 2) */
#if defined(__GNUC__) && !defined(__clang__)
#pragma GCC optimize("Os")
#endif

/* maximum number of variables (size of the on-stack exponent buffers) */
#define GMAXV 12

/* Sparse distributed polynomial over Q: n terms (capacity cap), sorted by
 * decreasing monomial; see the file header for the layout. */
typedef struct {
    uint32_t n, cap;
    E **c;       /* rational coefficients */
    uint16_t *e; /* n * nv exponents */
} GP;

static int g_nv;
static int g_order; /* 0 lex, 1 grevlex */
void gbasis_reset_statics(void); /* cas.c eval_impl: state an error may have left set */
void gbasis_reset_statics(void) { g_nv = 0; g_order = 0; }

/*
 * mcmp -- compare two exponent vectors in the current term order (g_order).
 * Returns <0, 0, >0 when monomial a is smaller than, equal to, or larger
 * than b.
 *   lex:     compare exponents of variable 0, then 1, ... (first difference
 *            decides; larger exponent = larger monomial).
 *   grevlex: compare total degree first; ties are broken by the LAST
 *            variable, where the monomial with the SMALLER exponent is the
 *            larger one (graded reverse lexicographic order).
 * Cost O(g_nv).
 */
static int mcmp(const uint16_t *a, const uint16_t *b) {
    if (g_order == 1) {
        uint32_t da = 0, db = 0;
        for (int i = 0; i < g_nv; i++) {
            da += a[i];
            db += b[i];
        }
        if (da != db) return da < db ? -1 : 1;
        for (int i = g_nv - 1; i >= 0; i--)
            if (a[i] != b[i]) return a[i] > b[i] ? -1 : 1;
        return 0;
    }
    for (int i = 0; i < g_nv; i++)
        if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;
    return 0;
}

/* Allocate an empty GP with room for `cap` terms (at least 1) in scratch.
 * Throws CAS_ERR_MEMORY (via salloc) when scratch is exhausted. */
static GP gp_alloc(uint32_t cap) {
    GP p;
    p.n = 0;
    p.cap = cap ? cap : 1;
    p.c = salloc(sizeof(E *) * p.cap);
    p.e = salloc(sizeof(uint16_t) * p.cap * (size_t)g_nv);
    return p;
}

/* Append the term c * x^e at the end of *p (the caller guarantees that the
 * order stays decreasing).  When full, the arrays are copied into a new
 * scratch block of twice the capacity; the old block is simply abandoned
 * (scratch has no free), so amortised cost is O(g_nv) per term. */
static void gp_push(GP *p, E *c, const uint16_t *e) {
    if (p->n == p->cap) {
        GP q = gp_alloc(p->cap * 2);
        memcpy(q.c, p->c, sizeof(E *) * p->n);
        memcpy(q.e, p->e, sizeof(uint16_t) * p->n * (size_t)g_nv);
        q.n = p->n;
        *p = q;
    }
    p->c[p->n] = c;
    memcpy(p->e + (size_t)p->n * g_nv, e, sizeof(uint16_t) * (size_t)g_nv);
    p->n++;
}

/* exponent vector (g_nv entries) of term i of GP p; EXP(p, 0) is LM(p) */
#define EXP(p, i) ((p).e + (size_t)(i) * g_nv)

/*
 * gp_axpy -- return a + s * x^m * b as a new GP (a and b are not modified).
 * s is a rational coefficient, m an exponent vector.  Multiplying b by a
 * monomial preserves its term order, so the result is produced by a single
 * merge of two sorted term lists, like merging sorted arrays: O(a.n + b.n)
 * monomial comparisons plus the rational arithmetic.  Coefficients that
 * cancel to zero are dropped, so the result is again a valid GP.
 * This is the only arithmetic primitive: subtraction, S-polynomials and
 * reduction steps are all expressed through it.
 */
static GP gp_axpy(GP a, E *s, const uint16_t *m, GP b) {
    GP r = gp_alloc(a.n + b.n + 1);
    uint16_t tmp[GMAXV];
    uint32_t i = 0, j = 0;
    while (i < a.n || j < b.n) {
        int c;
        /* tmp = exponent of the next term of x^m * b; c compares heads
         * (an exhausted list counts as smaller than anything) */
        if (j < b.n)
            for (int k = 0; k < g_nv; k++) tmp[k] = (uint16_t)(EXP(b, j)[k] + m[k]);
        if (i >= a.n) c = -1;
        else if (j >= b.n) c = 1;
        else c = mcmp(EXP(a, i), tmp);
        if (c > 0) {
            gp_push(&r, a.c[i], EXP(a, i));
            i++;
        } else if (c < 0) {
            gp_push(&r, num_mul(s, b.c[j]), tmp);
            j++;
        } else {
            E *v = num_add(a.c[i], num_mul(s, b.c[j]));
            if (!num_is_zero(v)) gp_push(&r, v, tmp);
            i++;
            j++;
        }
    }
    return r;
}

/* Return p divided by its leading coefficient (a new GP; the zero
 * polynomial is returned unchanged). */
static GP gp_monic(GP p) {
    if (!p.n) return p;
    E *il = num_inv(p.c[0]);
    GP r = gp_alloc(p.n);
    for (uint32_t i = 0; i < p.n; i++) gp_push(&r, num_mul(p.c[i], il), EXP(p, i));
    return r;
}

/* 1 if monomial x^a divides x^b, i.e. a[k] <= b[k] for every variable. */
static int divides(const uint16_t *a, const uint16_t *b) {
    for (int k = 0; k < g_nv; k++)
        if (a[k] > b[k]) return 0;
    return 1;
}

/*
 * gp_reduce -- full (complete) reduction of p modulo G[0..ng-1]; returns
 * the normal form r, in which no term is divisible by any LM(G[k]).
 *
 * Classic multivariate division (Cox/Little/O'Shea, sec. 2.3): look at the
 * leading term of the running polynomial p.  If some LM(G[k]) divides it,
 * cancel it with p := p - (lc(p)/lc(G[k])) * x^(LM(p)-LM(G[k])) * G[k]
 * (the first such k is used); otherwise move the leading term into the
 * remainder r.  Each step strictly decreases LM(p) in a well-order, so the
 * loop terminates; G elements with n == 0 (dropped during minimisation) are
 * skipped.  Removing the leading term is O(1): the GP view is advanced by
 * one term, sharing the arrays.
 *
 * Throws CAS_ERR_UNSUPPORTED after 200000 steps (coefficient / term
 * explosion), polls for interrupts every 64 steps.  Result in scratch.
 */
static GP gp_reduce(GP p, GP *G, uint32_t ng) {
    GP r = gp_alloc(p.n + 4);
    uint16_t m[GMAXV];
    uint32_t iter = 0;
    while (p.n) {
        if ((++iter & 63) == 0) poll_intr();
        if (iter > 200000) cas_throw(CAS_ERR_UNSUPPORTED, "gbasis: reduction too long");
        int done = 0;
        for (uint32_t k = 0; k < ng; k++) {
            if (!G[k].n || !divides(EXP(G[k], 0), EXP(p, 0))) continue;
            for (int q = 0; q < g_nv; q++) m[q] = (uint16_t)(EXP(p, 0)[q] - EXP(G[k], 0)[q]);
            E *s = num_neg(num_div(p.c[0], G[k].c[0]));
            p = gp_axpy(p, s, m, G[k]);
            done = 1;
            break;
        }
        if (!done) {
            gp_push(&r, p.c[0], EXP(p, 0));
            /* drop the leading term of p */
            GP q = p;
            q.c++;
            q.e += g_nv;
            q.n--;
            q.cap--;
            p = q;
        }
    }
    return r;
}

/*
 * spoly -- S-polynomial of nonzero a and b:
 *     S(a, b) = (L / LT(a)) * a - (L / LT(b)) * b,  L = lcm(LM(a), LM(b)),
 * whose leading terms cancel by construction.  ma / mb are the exponent
 * vectors of L / LM(a) and L / LM(b); the coefficient factors are 1/lc(a)
 * and -1/lc(b) (both 1 / -1 for the monic basis elements used here).
 */
static GP spoly(GP a, GP b) {
    uint16_t l[GMAXV], ma[GMAXV], mb[GMAXV];
    for (int k = 0; k < g_nv; k++) {
        l[k] = EXP(a, 0)[k] > EXP(b, 0)[k] ? EXP(a, 0)[k] : EXP(b, 0)[k];
        ma[k] = (uint16_t)(l[k] - EXP(a, 0)[k]);
        mb[k] = (uint16_t)(l[k] - EXP(b, 0)[k]);
    }
    GP z = gp_alloc(1);
    GP t = gp_axpy(z, num_inv(a.c[0]), ma, a);
    return gp_axpy(t, num_neg(num_inv(b.c[0])), mb, b);
}

/* --------------------------------------------------------- conversion --- */
/*
 * e2gp_term -- split one expanded term t (a product, a power, a symbol or a
 * number) into a rational coefficient *c and an exponent vector ex over
 * vars[0..g_nv-1].  Every non-numeric factor must be a variable or a
 * variable raised to a non-negative small integer power (at most 60000, so
 * the uint16_t exponents cannot overflow from a single factor).
 * Returns 1 on success, 0 if t is not a monomial with coefficients in Q
 * (e.g. contains a parameter, a float, sqrt(2), or a negative power).
 */
static int e2gp_term(E *t, E **vars, E **c, uint16_t *ex) {
    for (int k = 0; k < g_nv; k++) ex[k] = 0;
    *c = K->c1;
    E **fs = t->t == E_MUL ? EK(t) : &t;
    uint32_t n = t->t == E_MUL ? t->n : 1;
    for (uint32_t i = 0; i < n; i++) {
        E *f = fs[i];
        if (is_exactnum(f)) {
            *c = num_mul(*c, f);
            continue;
        }
        E *b = f->t == E_POW ? K0(f) : f;
        long k = 1;
        if (f->t == E_POW && !num_is_small_int(K1(f), &k)) return 0;
        int found = 0;
        for (int v = 0; v < g_nv; v++)
            if (expr_eq(b, vars[v])) {
                if (k < 0 || k > 60000) return 0;
                ex[v] = (uint16_t)(ex[v] + k);
                found = 1;
            }
        if (!found) return 0;
    }
    return 1;
}

/* compare the monomials of terms i and j of *p in the current order */
static int cmp_idx_terms(GP *p, uint32_t i, uint32_t j) { return mcmp(EXP(*p, i), EXP(*p, j)); }

/*
 * e2gp -- convert expression e to a GP over vars.  e is fully expanded,
 * each term converted by e2gp_term, the terms sorted into decreasing order
 * (insertion sort, O(n^2) but inputs are small) and equal monomials merged
 * (terms whose coefficients cancel are dropped).  The canonical order of
 * the simplifier is unrelated to the Groebner term order, hence the sort.
 * Returns 1 and stores the result in *out, or 0 if e is not a polynomial in
 * vars with rational coefficients.
 */
static int e2gp(E *e, E **vars, GP *out) {
    E *x = expand(e);
    E **ts = x->t == E_ADD ? EK(x) : &x;
    uint32_t n = x->t == E_ADD ? x->n : 1;
    GP p = gp_alloc(n + 1);
    uint16_t ex[GMAXV];
    for (uint32_t i = 0; i < n; i++) {
        E *c;
        if (is_zero(ts[i])) continue;
        if (!e2gp_term(ts[i], vars, &c, ex)) return 0;
        gp_push(&p, c, ex);
    }
    /* sort descending (insertion; inputs are small) and merge equal monomials */
    for (uint32_t i = 1; i < p.n; i++)
        for (uint32_t j = i; j > 0 && cmp_idx_terms(&p, j - 1, j) < 0; j--) {
            E *tc = p.c[j]; p.c[j] = p.c[j - 1]; p.c[j - 1] = tc;
            uint16_t te[GMAXV];
            memcpy(te, EXP(p, j), sizeof(uint16_t) * (size_t)g_nv);
            memcpy(EXP(p, j), EXP(p, j - 1), sizeof(uint16_t) * (size_t)g_nv);
            memcpy(EXP(p, j - 1), te, sizeof(uint16_t) * (size_t)g_nv);
        }
    GP q = gp_alloc(p.n + 1);
    for (uint32_t i = 0; i < p.n;) {
        E *c = p.c[i];
        uint32_t j = i + 1;
        while (j < p.n && mcmp(EXP(p, i), EXP(p, j)) == 0) c = num_add(c, p.c[j++]);
        if (!num_is_zero(c)) gp_push(&q, c, EXP(p, i));
        i = j;
    }
    *out = q;
    return 1;
}

/* Convert a GP back into an automatically simplified expression
 * sum c_i * prod vars[k]^e_ik (the zero polynomial gives the empty sum). */
static E *gp2e(GP p, E **vars) {
    E **ts = salloc(sizeof(E *) * (p.n + 1));
    for (uint32_t i = 0; i < p.n; i++) {
        E **fs = salloc(sizeof(E *) * (size_t)(g_nv + 1));
        uint32_t nf = 0;
        fs[nf++] = p.c[i];
        for (int k = 0; k < g_nv; k++)
            if (EXP(p, i)[k]) fs[nf++] = s_pow(vars[k], mk_int(EXP(p, i)[k]));
        ts[i] = s_mul(nf, fs);
    }
    return s_add(p.n, ts);
}

/* ------------------------------------------------------------ Buchberger --- */
/* A critical pair: indices of two basis elements and the exponent vector of
 * lcm(LM(G[i]), LM(G[j])), cached for selection and the chain criterion. */
typedef struct {
    uint32_t i, j;
    uint16_t lcm[GMAXV];
} gpair;

/*
 * groebner -- reduced Groebner basis of the ideal generated by polys.
 *
 *   polys  E_LIST of polynomials; an equation a = b stands for a - b.
 *   vars   E_LIST of variables (symbols, checked by the gbasis command);
 *          vars[0] is the largest variable.
 *   order  0 = lex, 1 = grevlex (see mcmp).
 *
 * Returns an E_LIST of monic polynomials sorted by ascending leading
 * monomial (for lex: triangular, last variable first), [1] if the ideal is
 * the whole ring (inconsistent system), the empty list if every input is
 * zero, or NULL if some input is not a polynomial in vars over Q (the
 * caller decides how to report that).  All memory is scratch.
 *
 * Errors: CAS_ERR_UNSUPPORTED via cas_throw when more than GMAXV variables
 * are given or one of the size / step limits described in the file header
 * is exceeded; interrupts and CAS_ERR_MEMORY propagate from poll_intr /
 * salloc.  On a throw g_nv / g_order are left modified (harmless: every
 * call sets them first).
 *
 * Bookkeeping: G[0..ng-1] is the growing basis (cap 256), P[0..np-1] the
 * pending pairs (unordered; removal swaps in the last pair), and done is a
 * cap x cap byte matrix with done[i*cap+j] = 1 once pair (i, j) has left P
 * (treated or discarded) -- exactly the information the chain criterion
 * needs.
 */
E *groebner(E *polys, E *vars, int order) {
    if (vars->n > GMAXV) cas_throw(CAS_ERR_UNSUPPORTED, "gbasis: too many variables");
    int old_nv = g_nv, old_order = g_order;
    g_nv = (int)vars->n;
    g_order = order;
    uint32_t cap = 256;
    GP *G = salloc(sizeof(GP) * cap);
    uint32_t ng = 0;
    /* convert the inputs; zero polynomials are dropped, others made monic */
    for (uint32_t i = 0; i < polys->n; i++) {
        GP p;
        E *q = EK(polys)[i];
        if (IFN(q, F_EQ)) q = s_sub(K0(q), K1(q));
        if (!e2gp(q, EK(vars), &p)) {
            g_nv = old_nv;
            g_order = old_order;
            return NULL;
        }
        if (!p.n) continue;
        if (ng >= cap) cas_throw(CAS_ERR_UNSUPPORTED, "gbasis: basis too large");
        G[ng++] = gp_monic(p);
    }
    uint32_t pcap = 4096, np = 0;
    gpair *P = salloc(sizeof(gpair) * pcap);
    uint8_t *done = salloc(cap * cap);
    memset(done, 0, cap * cap);
    /* ADDPAIR(a, b): append pair (a, b) to P with its cached lcm exponent */
#define ADDPAIR(a, b)                                                                                       \
    do {                                                                                                    \
        if (np >= pcap) cas_throw(CAS_ERR_UNSUPPORTED, "gbasis: too many pairs");                           \
        P[np].i = (a);                                                                                      \
        P[np].j = (b);                                                                                      \
        for (int k_ = 0; k_ < g_nv; k_++)                                                                   \
            P[np].lcm[k_] = EXP(G[a], 0)[k_] > EXP(G[b], 0)[k_] ? EXP(G[a], 0)[k_] : EXP(G[b], 0)[k_];   \
        np++;                                                                                               \
    } while (0)
    for (uint32_t i = 0; i < ng; i++)
        for (uint32_t j = i + 1; j < ng; j++) ADDPAIR(i, j);
    uint32_t iters = 0;
    while (np) {
        poll_intr();
        if (++iters > 5000) cas_throw(CAS_ERR_UNSUPPORTED, "gbasis: too many steps");
        /* normal strategy: smallest lcm in the term order (linear scan of P) */
        uint32_t best = 0;
        for (uint32_t k = 1; k < np; k++)
            if (mcmp(P[k].lcm, P[best].lcm) < 0) best = k;
        gpair pr = P[best];
        P[best] = P[--np];
        done[pr.i * cap + pr.j] = done[pr.j * cap + pr.i] = 1;
        /* product criterion: coprime leading monomials => S reduces to 0 */
        int coprime = 1;
        for (int k = 0; k < g_nv; k++)
            if (EXP(G[pr.i], 0)[k] && EXP(G[pr.j], 0)[k]) coprime = 0;
        if (coprime) continue;
        /* chain criterion: LM(G[k]) | lcm(i,j) and pairs (i,k), (j,k) are no
         * longer pending => S(i,j) is a combination of S(i,k) and S(k,j)
         * and need not be reduced */
        int chain = 0;
        for (uint32_t k = 0; k < ng && !chain; k++) {
            if (k == pr.i || k == pr.j || !G[k].n) continue;
            if (divides(EXP(G[k], 0), pr.lcm) && done[pr.i * cap + k] && done[pr.j * cap + k]) chain = 1;
        }
        if (chain) continue;
        /* reduce the S-polynomial; a nonzero normal form is a new basis
         * element (its LM is not divisible by any existing LM) */
        GP s = spoly(G[pr.i], G[pr.j]);
        GP r = gp_reduce(s, G, ng);
        if (!r.n) continue;
        r = gp_monic(r);
        if (ng >= cap) cas_throw(CAS_ERR_UNSUPPORTED, "gbasis: basis too large");
        G[ng] = r;
        for (uint32_t k = 0; k < ng; k++)
            if (G[k].n) ADDPAIR(k, ng);
        ng++;
        /* constant: ideal is (1) */
        int isconst = 1;
        for (int k = 0; k < g_nv; k++)
            if (EXP(r, 0)[k]) isconst = 0;
        if (isconst) {
            E *one = K->c1;
            g_nv = old_nv;
            g_order = old_order;
            return s_list(1, &one);
        }
    }
    /* minimise: drop elements whose leading monomial is divisible by another's.
     * Among elements with equal leading monomials the lowest index survives
     * (j < i test).  Dropping is marked by n = 0. */
    for (uint32_t i = 0; i < ng; i++) {
        if (!G[i].n) continue;
        for (uint32_t j = 0; j < ng; j++) {
            if (i == j || !G[j].n) continue;
            if (divides(EXP(G[j], 0), EXP(G[i], 0)) && (mcmp(EXP(G[j], 0), EXP(G[i], 0)) != 0 || j < i)) {
                G[i].n = 0;
                break;
            }
        }
    }
    /* interreduce: replace each R[i] by LT(R[i]) + NF(tail(R[i]), others).
     * After minimisation no other LM divides LT(R[i]), so only the tail can
     * change; reducing in place with the already updated R[j] (j < i) is
     * fine because the leading monomials never change.  The result is the
     * unique reduced Groebner basis of the ideal. */
    GP *R = salloc(sizeof(GP) * (ng + 1));
    uint32_t nr = 0;
    for (uint32_t i = 0; i < ng; i++)
        if (G[i].n) R[nr++] = G[i];
    for (uint32_t i = 0; i < nr; i++) {
        GP lead = gp_alloc(1);
        gp_push(&lead, R[i].c[0], EXP(R[i], 0));
        GP tail = R[i];
        tail.c++;
        tail.e += g_nv;
        tail.n--;
        GP *others = salloc(sizeof(GP) * (nr + 1));
        uint32_t no = 0;
        for (uint32_t j = 0; j < nr; j++)
            if (j != i) others[no++] = R[j];
        GP red = gp_reduce(tail, others, no);
        /* lead + red: the leading term (coefficient 1) is unchanged */
        uint16_t zero[GMAXV] = {0};
        R[i] = gp_axpy(lead, K->c1, zero, red);
    }
    /* sort by leading monomial ascending (triangular for lex: polynomials in
     * the last variable only come first) */
    for (uint32_t i = 1; i < nr; i++)
        for (uint32_t j = i; j > 0 && mcmp(EXP(R[j - 1], 0), EXP(R[j], 0)) > 0; j--) {
            GP t = R[j]; R[j] = R[j - 1]; R[j - 1] = t;
        }
    E **out = salloc(sizeof(E *) * (nr + 1));
    for (uint32_t i = 0; i < nr; i++) out[i] = gp2e(R[i], EK(vars));
    g_nv = old_nv;
    g_order = old_order;
    return s_list(nr, out);
}
